#!/bin/sh
# Fetch the images of docker-compose.yaml by digest into images/ (generated by hydo compose; hydo-build
# never pulls). Needs hydo-fetch-image (it comes with hydo) and network access, once.
set -eu
cd "$(dirname "$0")"
F=${HYDO_FETCH_IMAGE:-$(command -v hydo-fetch-image || true)}
[ -n "$F" ] || { echo "fetch-images.sh: hydo-fetch-image not found (put hydo's bin directory on PATH, or set HYDO_FETCH_IMAGE)" >&2; exit 1; }
mkdir -p images
[ -e images/ghost-6.75.0-alpine-arm64-oci ] || "$F" docker.io/library/ghost sha256:12ede333deb590bb1476056857f4028bfa26bdaade15f2cf5c40e6165d7e4123 ghost:6.75.0-alpine images/ghost-6.75.0-alpine-arm64-oci
[ -f images/ghost-6.75.0-alpine-amd64.docker.tar ] || "$F" docker.io/library/ghost sha256:9c4d6d91fdae425b5d75675a46ac16a53286c1f53eb05bf37902a5668726e04b ghost:6.75.0-alpine images/ghost-6.75.0-alpine-amd64.docker.tar
[ -e images/mysql-8.0.44-arm64-oci ] || "$F" docker.io/library/mysql sha256:2c4989e05aa3ceb8cb6eb8a1b1f38ffa361eac2fec96ec67705d1b21c6390527 mysql:8.0.44 images/mysql-8.0.44-arm64-oci
[ -f images/mysql-8.0.44-amd64.docker.tar ] || "$F" docker.io/library/mysql sha256:f7878bec832c6be5e61c39d3949651be8aa977daf875089b4560ae1434d2cb9c mysql:8.0.44 images/mysql-8.0.44-amd64.docker.tar
ls -ld images/ghost-6.75.0-alpine-amd64.docker.tar images/ghost-6.75.0-alpine-arm64-oci images/mysql-8.0.44-amd64.docker.tar images/mysql-8.0.44-arm64-oci
